"""Integral parity between the sheet-difference and odd coinvariant lattices."""
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[3]
OUT=ROOT/'research/benincasa/results/rank12-node-sheet-coinvariant-parity.json'

# N=Z<e+,e->, iota swaps the basis.  N^- is generated by d=e+-e-.
# In N_iota,- = N/<e++e->, [e-]=-[e+], hence d maps to 2[e+].
smith_diagonal=[2]
packet={
 'schema':'marici.benincasa.rank12_node_sheet_coinvariant_parity.v1',
 'sheet_lattice':'Z<e_plus,e_minus>',
 'deck_action':[[0,1],[1,0]],
 'anti_invariant_sublattice_generator':'d=e_plus-e_minus',
 'odd_coinvariant_generator':'c=[e_plus], with [e_minus]=-[e_plus]',
 'comparison':'d -> 2*c',
 'smith_diagonal':smith_diagonal,
 'kernel_rank':0,
 'cokernel':'Z/2',
 'rational_projector':'(1-iota)/2',
 'conclusion':'the sheet-difference and primitive odd-cycle lattices agree over Q but differ by a canonical index-two parity defect over Z'
}
OUT.parent.mkdir(parents=True,exist_ok=True);OUT.write_text(json.dumps(packet,indent=2)+'\n');print(json.dumps(packet))
